// SOFA2 ADMIN — Bold, dark, modern editorial style
// ----------------------------------------------------------------------

export const SOFA2_ADMIN_ROOT = '/sofa2/admin';

export type Sofa2AdminColumn = {
  key: string;
  label: string;
  type?: 'text' | 'status' | 'money' | 'number';
};

export type Sofa2AdminModule = {
  slug: string;
  name: string;
  description: string;
  icon: string;
  stats: { label: string; value: string; trend?: string }[];
  columns: Sofa2AdminColumn[];
  rows: Record<string, string | number>[];
  actions?: string[];
};

export type Sofa2AdminGroup = {
  slug: string;
  name: string;
  icon: string;
  modules: Sofa2AdminModule[];
};

const money = (v: number) => v;

function mod(
  slug: string,
  name: string,
  description: string,
  icon: string,
  stats: Sofa2AdminModule['stats'],
  columns: Sofa2AdminColumn[],
  rows: Record<string, string | number>[],
  actions?: string[]
): Sofa2AdminModule {
  return { slug, name, description, icon, stats, columns, rows, actions };
}

const STATUS_COL: Sofa2AdminColumn = { key: 'status', label: 'Trạng thái', type: 'status' };

// ----------------------------------------------------------------------
// CMS
// ----------------------------------------------------------------------

const cmsPage = (slug: string, name: string, path: string, rows?: Record<string, string | number>[]) =>
  mod(
    slug,
    name,
    `Quản lý nội dung, bố cục và trạng thái xuất bản cho ${name.toLowerCase()} (${path}).`,
    'solar:document-text-bold-duotone',
    [
      { label: 'Khối nội dung', value: '14' },
      { label: 'Lượt xem 30 ngày', value: '24.6K', trend: '+14%' },
      { label: 'Bản nháp', value: '3' },
      { label: 'Cập nhật cuối', value: '14/09' },
    ],
    [
      { key: 'block', label: 'Khối nội dung' },
      { key: 'type', label: 'Loại' },
      STATUS_COL,
      { key: 'updated', label: 'Cập nhật' },
      { key: 'author', label: 'Người sửa' },
    ],
    (rows ?? [
      {
        block: 'Hero bold editorial',
        type: 'Banner',
        status: 'Đã xuất bản',
        updated: '14/09/2026',
        author: 'Minh Anh',
      },
      {
        block: 'Câu thương hiệu LUXE',
        type: 'Rich text',
        status: 'Đã xuất bản',
        updated: '10/09/2026',
        author: 'Thu Hà',
      },
      {
        block: 'Bộ sưu tập Scandinavian',
        type: 'Danh sách SP',
        status: 'Bản nháp',
        updated: '09/09/2026',
        author: 'Đức Anh',
      },
      {
        block: 'Đánh giá khách hàng',
        type: 'Slider',
        status: 'Đã xuất bản',
        updated: '02/09/2026',
        author: 'Minh Anh',
      },
      {
        block: 'CTA cuối trang',
        type: 'Banner',
        status: 'Tạm ẩn',
        updated: '28/08/2026',
        author: 'Thu Hà',
      },
    ]).map((row, index) => ({
      id: String(row.id ?? `cms-${slug}-${index + 1}`),
      heading: String(row.heading ?? row.block ?? name),
      content: String(row.content ?? `${String(row.block ?? name)} — nội dung mẫu được quản lý từ CMS LUXE Sofa.`),
      image: String(row.image ?? (slug === 'about' ? SOFA2_PAGE_IMAGES.aboutHero : SOFA2_PAGE_IMAGES.product1)),
      ctaLabel: String(row.ctaLabel ?? (index === 0 ? 'Tìm hiểu thêm' : '')),
      ctaLink: String(row.ctaLink ?? (index === 0 ? path : '')),
      order: Number(row.order ?? index + 1),
      metaTitle: String(row.metaTitle ?? `${name} | LUXE Sofa`),
      metaDescription: String(row.metaDescription ?? `Thông tin ${name.toLowerCase()} từ LUXE Sofa.`),
      ogImage: String(row.ogImage ?? row.image ?? (slug === 'about' ? SOFA2_PAGE_IMAGES.aboutHero : SOFA2_PAGE_IMAGES.product1)),
      indexable: String(row.indexable ?? 'Có'),
      ...row,
    })),
    ['Thêm khối', 'Xem trước', 'Xuất bản']
  );

